["Defeat Festergut while none of the players in your raid group ever had 3 stacks of Inoculated"]="Победите Тухлопуза в рейде на 10 игроков. Эффект \"Невосприимчивость к гнили\" не должен суммироваться ни на одном участнике рейда 3 раза.",
