["Defeat Flame Leviathan with at least 2 Orbital Defense Systems active"]="Убейте Огненного Левиафана в рейде на 10 игроков, оставив работающими хотя бы две орбитальных системы защиты.",
["Defeat Flame Leviathan with at least 3 Orbital Defense Systems active"]="Убейте Огненного Левиафана в рейде на 10 игроков, оставив работающими хотя бы три орбитальных системы защиты.",
