["Defeat General Bjarngrim inside the Halls of Lightning on Heroic or higher difficulty, while he still has atleast one Lightning Charge."]="Убейте генерала Бьярнгрима в Чертогах Молний в героическом режиме, пока он находится под действием временного электрического заряда.",
