["Defeat Grand Magus Telestra inside The Nexus on Heroic or higher difficulty after having killed all of her images within 5 seconds of each other."]="Одержите победу над великой ведуньей Телестрой в Нексусе в героическом режиме, убивая все ее образы с интервалом не более 5 секунд.",
["Defeat Grand Widow Faerlina inside Naxxramas in her Classic version on Ascended difficulty without dispelling or preventing Sadism."]="Убейте Великую вдову Фарлину в Наксрамасе в рейде на 25 игроков, не развеивая \"бешенство\" и не пытаясь избежать его.",
