["Defeat Ley-Guardian Eregos inside The Oculus on Heroic or higher difficulty within 20 minutes of defeating Drakos the Interrogator."]="Убейте хранителя энергии Эрегоса в Окулусе в героическом режиме в течение 20 минут после смерти Пытателя.",
["Defeat Ley-Guardian Eregos inside The Oculus on Heroic or higher difficulty without anyone in your party engaging combat with Eregos while riding an Amber Skytalon."]="Убейте хранителя энергии Эрегоса в Окулусе группой, в которой никто не оседлал янтарного дракона. Это нужно выполнить в героическом режиме.",
["Defeat Ley-Guardian Eregos inside The Oculus on Heroic or higher difficulty without anyone in your party engaging combat with Eregos while riding an Emerald Skytalon."]="Убейте хранителя энергии Эрегоса в Окулусе группой, в которой никто не оседлал изумрудного дракона. Это нужно выполнить в героическом режиме.",
["Defeat Ley-Guardian Eregos inside The Oculus on Heroic or higher difficulty without anyone in your party engaging combat with Eregos while riding an Ruby Skytalon."]="Убейте хранителя энергии Эрегоса в Окулусе группой, в которой никто не оседлал рубинового дракона. Это нужно выполнить в героическом режиме.",
["Defeat Loatheb inside Naxxramas in his Classic version on Ascended difficulty without killing any Energizing Spores."]="Убейте Лотхиба в рейде на 25 игроков, не убив ни одну спору.",
