["Defeat Loken inside the Halls of Lightning on Heroic or higher difficulty, without any player taking damage from Lightning Nova or Static Pulse while more than 50 yards away from Loken."]="Убейте Локена в Чертогах Молний в героическом режиме за 2 минуты или быстрее.",
["Defeat Lord Jaraxxus while at least two Mistresses of Pain are alive"]="Победите лорда Джараксуса в рейде из 10 игроков, оставив в живых хотя бы две госпожи Боли.",
["Defeat Lord Marrowgar without any raid member remaining impaled for more than 8 seconds"]="Убейте Лорда Ребрада в рейде на 10 игроков. Ни один участник рейда не должен быть проколот костяным шипом дольше 8 сек.",
["Defeat Maexxna inside Naxxramas in her Classic version on Ascended difficulty within 20 minutes of Anub'Rekhan's death."]="Убейте Мексну в течение 20 минут после смерти Ануб'Рекана в рейде на 25 игроков.",
["Defeat Maexxna inside Naxxramas in her Classic version on Mythic difficulty within 20 minutes of Anub'Rekhan's death."]="Убейте Мексну в течение 20 минут после смерти Ануб'Рекана в рейде на 10 игроков.",
