["Defeat Moorabi inside Gundrak on Heroic or higher difficulty without allowing Moorabi to transform into the Avatar of Mam'toth."]="Убейте Мураби в Гундраке в героическом режиме, не дав ему превратиться в мамонта во время боя.",
