["Defeat Onyxia in her Classic version on Normal difficulty in less than 8 minutes after starting the encounter."]="Победите Ониксию менее чем за 5 минут в рейде на 10 игроков.",
["Defeat Onyxia in her Classic version on Normal difficulty without anyone taking damage from a Deep Breath."]="Победите Ониксию, не позволив ни одному из участников рейда для 10 игроков попасть под воздействие \"Глубокого вдоха\".",
["Defeat Onyxia in her Wrath of the Lich King version on Normal Difficulty in less than 8 minutes"]="Победите Ониксию менее чем за 5 минут в рейде на 25 игроков.",
["Defeat Onyxia in her Wrath of the Lich King version on Normal Difficulty without anyone taking damage from a Deep Breath."]="Победите Ониксию, не позволив ни одному из участников рейда для 25 человек попасть под воздействие \"Глубокого вдоха\".",
["Defeat Ossirian the Unscarred."]="Убейте Оссириана Неуязвимого.",
["Defeat Overlord Wyrmthalak."]="Убейте Властителя Змейталака.",
["Defeat Patchwerk inside Naxxramas in his Classic version on Ascended difficulty within 3 minutes or less after engaging the encounter."]="Убейте Лоскутика в рейде на 25 игроков в течение 3 минут.",
["Defeat Patchwerk inside Naxxramas in his Classic version on Mythic difficulty within 3 minutes or less after engaging the encounter."]="Убейте Лоскутика в рейде на 10 игроков в течение 3 минут.",
["Defeat Pathaleon the Calculator on Heroic Difficulty."]="Убейте Паталеона Вычислителя в героическом режиме.",
["Defeat Pathaleon the Calculator."]="Убейте Паталеона Вычислителя.",
["Defeat Prince Keleseth inside Utgarde Keep on Heroic or higher difficulty without shattering any Frost Tombs."]="Убейте Принца Келесета в Крепости Утгард в героическом режиме, не разбив ни одной ледяной могилы.",
["Defeat Prince Malchezaar in Karazhan."]="Убейте Принца Малчезара в Каражане.",
["Defeat Princess Theradras."]="Убейте Принцессу Терадрас.",
["Defeat Professor Putricide without using Regurgitated Ooze on the Abomination"]="Убейте профессора Мерзоцида в рейде на 10 игроков, не используя способность поганища \"Рвотный слизнюк\".",
["Defeat Quagmirran on Heroic Difficulty."]="Убейте Зыбуна в героическом режиме.",
["Defeat Quagmirran."]="Убейте Зыбуна.",
