["Defeat Rotface without a Big Ooze casting Unstable Ooze Explosion"]="Убейте Гниломорда в рейде на 10 игроков, не позволив большому слизнюку применить заклинание \"Взрыв нестабильного слизнюка\".",
["Defeat Sapphiron in Naxxramas"]="Убейте Сапфирона в Наксрамасе в рейде на 10 игроков.",
["Defeat Sapphiron inside Naxxramas in his Classic version on Ascended difficulty without any player in your raid group exceeding 100 points of Frost Resistance from any source at any time during the encounter."]="Убейте Сапфирона в Наксрамасе в рейде на 25 игроков. Ни один из членов рейда не должен иметь значение защиты от холода выше 100.",
["Defeat Sapphiron inside Naxxramas in his Classic version on Mythic difficulty without any player in your raid group exceeding 100 points of Frost Resistance from any source at any time during the encounter."]="Убейте Сапфирона в Наксрамасе в рейде на 10 игроков. Ни один из членов рейда не должен иметь значение защиты от холода выше 100.",
["Defeat Sartharion the Onyx Guardian"]="Убейте Сартариона Ониксового Стража в рейде на 25 игроков.",
["Defeat Sartharion the Onyx Guardian and the Twilight Drakes with fewer than 21 players"]="Убейте Сартариона Ониксового Стража и Сумеречных в составе рейда из 20 игроков или менее в рейде на 25 игроков.",
["Defeat Sartharion the Onyx Guardian and the Twilight Drakes with fewer than 9 players"]="Убейте Сартариона Ониксового Стража и Сумеречных драконов в составе рейда из 8 игроков или менее в рейде на 10 игроков.",
["Defeat Sartharion the Onyx Guardian without getting hit by Lava Strike"]="Убейте Сартариона Ониксового Стража в рейде на 25 игроков, не попав под лавовые удары.",
["Defeat Sartharion the Onyx Guardian without getting hit by Lava Strike."]="Убейте Сартариона Ониксового Стража в рейде на 10 игроков, не попав под лавовые удары.",
["Defeat Shade of Eranikus."]="Убейте Тень Эраникуса.",
["Defeat Sindragosa without any member of your raid receiving more than 5 stacks of Mystic Buffet."]="Одолейте Синдрагосу в рейде на 10 игроков. Эффект \"Таинственная энергия\" не должен суммироваться ни на одном участнике рейда более 5 раз.",
["Defeat Sjonnir The Ironshaper inside the Halls of Stone on Heroic or higher difficulty, after killing atleast 5 Iron Sludge during the encounter."]="Одержите победу над Сьонниром Литейщиком в Чертогах Камня в героическом режиме и убейте в процессе 5 железных слякочей.",
["Defeat Skadi the Ruthless inside Utgarde Pinnacle on Heroic or higher difficulty after having killed Grauf by using all Harpoon Launcher's at the same time."]="Убейте Скади Безжалостного в героическом режиме, предварительно убив Грауфа за один бой со 100% до нуля.",
["Defeat Skadi the Ruthless inside Utgarde Pinnacle on Heroic or higher difficulty within 3 minutes or less of starting the encounter."]="Убейте Скади Безжалостного в героическом режиме в Вершине Утгард в течение 3 минут с момента начала испытания.",
["Defeat Slad'ran inside Gundrak on Heroic or higher difficulty without anyone in your group getting snake wrapped."]="Убейте Слад'рана в Гундраке в героическом режиме, не допустив, чтобы вокруг вас обвилась змея.",
["Defeat Talon King Ikiss on Heroic Difficulty."]="Убейте короля воронов Айкисса в героическом режиме.",
["Defeat Talon King Ikiss while wearing a Pilgrim's Hat and either a Pilgrim's Dress, Robe, or Attire."]="Нарядитесь в шляпу странника, а также в платье, наряд или одеяние странника, и в таком виде победите короля воронов Айкисса.",
["Defeat Talon King Ikiss."]="Убейте Короля воронов Айкисса.",
["Defeat Taragaman the Hungerer."]="Убейте Тарагамана Ненасытного.",
