["Defeat Thaddius inside Naxxramas in his Classic version on Mythic difficulty without any player in your raid group taking damage from Positive or Negative Repel after Thaddius has been defibrilated."]="Убейте Таддиуса в Наксрамасе в рейде на 10 игроков. Ни один участник рейда не должен соприкоснуться с носителем заряда противоположной полярности.",
