["Defeat The Four Horsemen inside Naxxramas in their Classic version on Mythic difficulty ensuring they all died within 15 seconds of each other."]="Убейте 4 всадников в Наксрамасе одного за одним с интервалом не более 15 секунд в рейде на 10 игроков.",
