["Defeat XT-002 Deconstructor without him recovering any health from XS-013 Scrapbots"]="Убейте Разрушителя XT-002 в рейде на 25 игроков, не позволив ему восстановить жизнь с помощью хламоботов XS-013.",
["Defeat Xevozz, Lavanthor, Ichoron, Zuramat the Obliterator, Erekem, and Moragg in The Violet Hold on Heroic Difficulty."]="Убейте Ксевозза, Лавантора, Гнойрона, Зурамата Уничтожителя, Эрекема и Морагга в Аметистовой крепости в героическом режиме.",
