["Defeat each boss in Ulduar in 10-player mode without allowing any raid member to die to that boss at any point during that raid lockout period."]="Убейте всех боссов в Ульдуаре в рейде на 10 игроков, не допустив смерти ни одного участника рейда от боссов за все время сохранения подземелья.",
["Defeat each boss in Ulduar in 25-player mode without allowing any raid member to die to that boss at any point during that raid lockout period."]="Убейте всех боссов в Ульдуаре в рейде на 25 игроков, не допустив смерти ни одного участника рейда от боссов за все время сохранения подземелья.",
