["Defeat every boss in Icecrown Citadel"]="Убейте всех боссов в Цитадели Ледяной Короны в рейде на 10 игроков.",
["Defeat every boss in Icecrown Citadel in Heroic mode."]="Убейте всех боссов в Цитадели ледяной Короны в рейде на 10 игроков в героическом режиме.",
["Defeat every boss in Ulduar"]="Убейте всех боссов Ульдуара в рейде на 10 игроков.",
