["Defeat every boss in the Trial of the Grand Crusader in Heroic mode."]="Одержите верх над всеми боссами во время испытания великого крестоносца в рейде героической сложности на 25 игроков.",
["Defeat every boss inside Naxxramas in its Classic version on Ascended difficulty within the same instance lockout without any player dying while any boss encounter is in progress."]="В течение одного сохраненного рейда убейте всех боссов в Наксрамасе в рейде на 10 игроков, не допустив смерти ни одного участника рейда.",
["Defeat every boss inside Naxxramas in its Classic version on Ascended difficulty."]="Убейте всех боссов в Наксрамасе в рейде на 25 игроков.",
["Defeat every boss inside Naxxramas in its Classic version on Mythic difficulty."]="Убейте всех боссов в Наксрамасе в рейде на 10 игроков.",
["Defeat every boss inside Naxxramas in their Wrath of the Lich King version on Ascended difficulty within the same instance lockout without any player dying while any boss encounter is in progress."]="В течение одного сохраненного рейда убейте всех боссов в Наксрамасе в рейде на 25 игроков, не допустив смерти ни одного участника рейда.",
["Defeat every boss inside the Molten Core on Normal difficulty."]="Убейте Рагнароса.",
["Defeat the Ahn'kahet: The Old Kingdom bosses on Heroic Difficulty."]="Убейте боссов Ан'кахет: Старое Королевство в героическом режиме.",
