["Defeat the Army of the Frozen Wastes within 4 minutes or less during the Kel'Thuzad encounter inside Naxxramas in his Classic version on Mythic difficulty."]="Убейте Кел'Тузада в Наксрамасе в рейде на 10 игроков, убив как минимум 18 поганищ в его комнате.",
