["Defeat the Assembly of Iron with Runemaster Molgeim as the last member alive"]="Победите Железное Собрание в рейде на 10 игроков, убив последним Мастера рун Молгейма.",
["Defeat the Assembly of Iron with Steelbreaker as the last member alive"]="Победите Железное Собрание в рейде на 10 игроков, убив последним Сталелома.",
