["Defeat the Assembly of Iron without allowing Stormcaller Brundir to damage anyone with Chain Lightning or Lightning Whirl"]="Победите Железное Собрание в рейде на 10 игроков, не позволив Буревестнику Брундиру причинить кому-нибудь урон \"Цепной молнией\" или \"Вихрем молний\".",
["Defeat the Azjol-Nerub bosses on Heroic Difficulty."]="Убейте боссов Азжол-Неруба в героическом режиме.",
