["Defeat the Blood Council without anyone in the raid taking more than 25,000 spell damage in a single hit"]="Победите Кровавый Совет в рейде на 25 игроков. Ни один участник рейда не должен получить более 25000 ед. магического урона за один удар.",
["Defeat the Caverns of Time: Stratholme bosses on Heroic Difficulty."]="Убейте боссов в зоне Пещеры Времени: Стратхольм в героическом режиме.",
["Defeat the Deathbringer before Mark of the Fallen Champion is cast five times"]="Убейте Смертоносного в рейде на 25 игроков, не позволив ему применить способность \"Метка падшего воителя\" более пяти раз.",
["Defeat the Deathbringer before Mark of the Fallen Champion is cast three times"]="Убейте Смертоносного в рейде на 10 игроков, не позволив ему применить способность \"Метка падшего воителя\" более трех раз.",
["Defeat the Devourer of Souls in The Forge of Souls on Heroic Difficulty without him successfully casting Phantom Blast."]="Убейте Пожирателя Душ в Кузне Душ в героическом режиме, прервав все его заклинания \"Призрачный взрыв\".",
["Defeat the Drak'Tharon Keep bosses on Heroic Difficulty."]="Убейте боссов Крепости Драк'Тарон в героическом режиме.",
