["Defeat the Halls of Lightning bosses on Heroic Difficulty."]="Убейте боссов в Чертогах Молний в героическом режиме.",
["Defeat the Infinite Corruptor inside the The Culling of Stratholme on Heroic or higher difficulty, before he can take full control over the Guardian of Time."]="Убейте Осквернителя из рода Бесконечности в героическом режиме Очищения Стратхольма",
["Defeat the Keeper bosses of Ulduar"]="Убейте Хранителей Ульдуара в рейде на 10 игроков.",
["Defeat the Lich King in Icecrown Citadel"]="Убейте Короля-лича в Цитадели Ледяной Короны в рейде на 10 игроков.",
["Defeat the Lich King in Icecrown Citadel in 10-player Heroic mode."]="Убейте Короля-лича в Цитадели Ледяной Короны в рейде на 10 игроков в героическом режиме.",
