["Defeat the Maiden of Grief inside the Halls of Stone on Heroic or higher difficulty within 60 seconds or less."]="Убейте Деву Скорби в Чертогах Камня в героическом режиме за 1 минуту или быстрее.",
["Defeat the Scarlet Crusade within the Scarlet Monastery."]="Убейте всех представителей Алого ордена в Монастыре Алого ордена.",
