["In Isle of Conquest, control the following vehicles:"]="Захватите контроль над перечисленными ниже транспортными средствами на Острове Завоеваний:",
["In Isle of Conquest, destroy 10 vehicles and 100 players with turrets."]="Уничтожьте 10 транспортных средств и 100 персонажей с помощью турелей на Острове Завоеваний.",
["In Isle of Conquest, disarm 25 bombs."]="Обезвредьте 25 бомб на Острове Завоеваний.",
["In Isle of Conquest, enter the enemy courtyard while their gates still stand."]="Во время битвы на Острове Завоеваний проникните во вражеский двор, не разрушая ворот.",
["In Isle of Conquest, kill 10 players with a Glaive Thrower without dying."]="С помощью метателя глеф убейте 10 игроков на Острове Завоеваний, при этом ни разу не погибнув.",
["In Warsong Gulch, kill a player who is under the effects of the speed power-up."]="Убейте персонажа, находящегося под воздействием увеличивающего скорость передвижения эффекта, в Ущелье Песни Войны.",
["In a single Alterac Valley battle, assault a graveyard, defend a graveyard, assault a tower, defend a tower and slay someone in the Field of Strife."]="В течение одного сражения в Альтеракской долине возьмите штурмом кладбище, защитите кладбище, возьмите штурмом башню, защитите башню и убейте врага на Поле брани.",
["In a single Eye of the Storm battle, get 5 honorable kills at each of the bases."]="Одержите 5 почетных побед на каждой базе за время одного сражения на Оке Бури.",
["In a single Eye of the Storm match, capture the flag 3 times without dying."]="В течение одного сражения на Оке Бури трижды захватите флаг, не умерев ни разу.",
["In a single Isle of Conquest battle, assault a base, defend a base, destroy a vehicle and kill a player."]="В течение одной битвы на Острове Завоеваний нападите на базу, защитите базу, уничтожьте транспортное средство и убейте персонажа.",
["In a single Isle of Conquest battle, kill a player at each of the following locations:"]="В течение одной битвы на Острове Завоеваний совершите убийства персонажей в каждой из перечисленных ниже областей:",
["In a single Isle of Conquest battle, use 5 Huge Seaforium Bombs on the enemy gates"]="Заложите 5 мощных сефориевых бомб у вражеских ворот за одно сражение на Острове Завоеваний.",
["In a single Isle of Conquest battle, use 5 Seaforium Bombs on the enemy gates."]="Заложите 5 сефориевых бомб у вражеских ворот за одно сражение на Острове Завоеваний.",
["In a single Warsong Gulch battle, carry and capture the flag 3 times without dying."]="В течение одного сражения в Ущелье Песни Войны трижды захватите флаг и доставьте на свою базу, не умерев ни разу.",
["In a single Warsong Gulch battle, kill 2 flag carriers before they leave the Silverwing Flag Room."]="В течение одного сражения в Ущелье Песни Войны убейте 2 персонажей, пытающихся вынести флаг из вашей комнаты.",
["In a single Warsong Gulch battle, kill 2 flag carriers before they leave the Warsong Flag Room."]="Убейте 2 персонажей, пытающихся вынести флаг из вашей комнаты, в течение одного сражения в Ущелье Песни Войны.",
["In the Trial of the Grand Crusader, reach a Tribute Chest with 50 attempts remaining"]="Проходя испытание великого крестоносца в рейде из 10 игроков, доберитесь до сундука с наградами. При этом у вас должно остаться не менее 50 попыток.",
["In the Trial of the Grand Crusader, reach a Tribute Chest with 50 attempts remaining and without allowing any raid member to die during any of the boss encounters in 25-player mode."]="Проходя испытание великого крестоносца в рейде из 25 игроков, доберитесь до сундука с наградами. При этом у вас должно остаться не менее 50 попыток и ни один участник рейда не должен погибнуть во время битв с боссами.",
["In the Trial of the Grand Crusader, reach a Tribute Chest with at least 25 attempts remaining"]="Проходя испытание великого крестоносца в рейде из 10 игроков, доберитесь до сундука с наградами. При этом у вас должно остаться не менее 25 попыток.",
